import{_ as i,o as a,c as t,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Vision-Language-Action Models (VLA)","description":"","frontmatter":{"title":"Vision-Language-Action Models (VLA)","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/vla.md","filePath":"en/tutorials/vla.md","lastUpdated":null}'),l={name:"en/tutorials/vla.md"};function o(r,e,s,h,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="vision-language-action-models-vla" tabindex="-1">Vision-Language-Action Models (VLA) <a class="header-anchor" href="#vision-language-action-models-vla" aria-label="Permalink to &quot;Vision-Language-Action Models (VLA)&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/vla">视觉-语言-动作模型 VLA</a><strong>Coverage</strong>: June 2025 – August 2026, tracing back to RT-1/RT-2, Open X-Embodiment, OpenVLA, π0, FAST and Diffusion Policy. <strong>Scale</strong>: 11 chapters + 2 appendices; Chapter 11 dissects 264 papers by arXiv id.</p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/vla">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>The tutorial assumes you know what a Transformer and a diffusion model are, and assumes nothing about robotics. It starts from a language-conditioned POMDP and the compounding-error bound of behaviour cloning, and derives from there why the field looks the way it does.</p><p>Its stated discipline about evidence is worth repeating, because it shapes the whole text: <strong>every number is attributed to the paper it came from, and wherever the author is offering an opinion rather than a fact, the text says so.</strong> Chapter 8 is described as &quot;the dirtiest part of the field&quot; and Chapter 8.6 argues that statistical methodology is the thing embodied AI is most short of.</p><p>Three claims carry the argument:</p><ul><li><strong>Action representation is the most underrated design decision in VLA</strong> (§2.3). It determines what the action head can express, how the backbone must be coupled, and what the latency budget looks like.</li><li><strong>Latency is not the same as model speed</strong> (§2.9). A fast model inside a slow loop is a slow robot, and the maths of that gap is developed explicitly.</li><li><strong>The architecture space is ten families, not two</strong> (Chapter 3): monolithic discrete, VLM + action expert, dual-system/hierarchical, 3D/spatial, latent action, world-action, reasoning, memory, multi-sensory, and cross-embodiment.</li></ul><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What this tutorial covers, in one sentence</li><li>0.2 Reading paths</li><li>0.2.1 How the papers were dissected (important)</li><li>0.3 Scope, and the relationship to the sister tutorials</li><li>0.4 The discipline about numbers</li></ul><h3 id="chapter-1-—-what-a-vla-is-from-intuition-to-strict-definition" tabindex="-1">Chapter 1 — What a VLA is: from intuition to strict definition <a class="header-anchor" href="#chapter-1-—-what-a-vla-is-from-intuition-to-strict-definition" aria-label="Permalink to &quot;Chapter 1 — What a VLA is: from intuition to strict definition&quot;">​</a></h3><ul><li>1.1 Starting from a concrete scene</li><li>1.2 VLA versus its three close relatives</li><li>1.3 Three historical threads that produced today&#39;s VLA</li><li>1.4 Why VLA is hard: five gaps relative to pure CV/NLP</li><li>1.5 A minimal mental model, in pseudocode</li><li>1.6 Terminology quick-reference</li></ul><h3 id="chapter-2-—-principles-all-the-mathematics-behind-turning-captioning-into-acting" tabindex="-1">Chapter 2 — Principles: all the mathematics behind turning captioning into acting <a class="header-anchor" href="#chapter-2-—-principles-all-the-mathematics-behind-turning-captioning-into-acting" aria-label="Permalink to &quot;Chapter 2 — Principles: all the mathematics behind turning captioning into acting&quot;">​</a></h3><ul><li>2.1 Formalisation: the language-conditioned POMDP</li><li>2.2 The imitation-learning objective and compounding error</li><li>2.3 Action representation: the most underrated design in all of VLA</li><li>2.4 Action chunking: why not decide step by step</li><li>2.5 Generative action heads: diffusion, flow matching, and their acceleration</li><li>2.6 The vision side: 2D, 2.5D or 3D</li><li>2.7 Backbone and conditioning: how the VLM and the action head connect</li><li>2.8 Training recipes: three stages and &quot;knowledge isolation&quot;</li><li>2.9 The mathematics of latency: why a fast model is not a fast robot</li></ul><h3 id="chapter-3-—-architecture-lineage-ten-families-one-map" tabindex="-1">Chapter 3 — Architecture lineage: ten families, one map <a class="header-anchor" href="#chapter-3-—-architecture-lineage-ten-families-one-map" aria-label="Permalink to &quot;Chapter 3 — Architecture lineage: ten families, one map&quot;">​</a></h3><ul><li>3.0 The master table</li><li>3.1 Monolithic discrete VLA: actions as tokens in the vocabulary</li><li>3.2 VLM + action expert: the de facto standard of 2025–2026</li><li>3.3 Dual-system / hierarchical: slow thinking, fast execution</li><li>3.4 3D and spatial enhancement</li><li>3.5 Latent actions: bringing unlabelled video in</li><li>3.6 World-action models (WAM): the most contested family of the period</li><li>3.7 Reasoning VLA: think before moving</li><li>3.8 Memory-equipped VLA</li><li>3.9 Multi-sensory: beyond vision</li><li>3.10 Cross-embodiment: one model, many robots</li></ul><h3 id="chapter-4-—-task-taxonomy-what-vla-is-actually-solving" tabindex="-1">Chapter 4 — Task taxonomy: what VLA is actually solving <a class="header-anchor" href="#chapter-4-—-task-taxonomy-what-vla-is-actually-solving" aria-label="Permalink to &quot;Chapter 4 — Task taxonomy: what VLA is actually solving&quot;">​</a></h3><ul><li>4.0 Why tasks come first</li><li>4.1 Tabletop single-arm manipulation: the default track</li><li>4.2 Bimanual and coordinated manipulation</li><li>4.3 Mobile manipulation</li><li>4.4 Dexterous manipulation</li><li>4.5 Humanoid and loco-manipulation</li><li>4.6 Vision-language navigation and embodied navigation</li><li>4.7 Autonomous-driving VLA</li><li>4.8 Vertical and long-tail scenarios</li><li>4.9 Four orthogonal axes of task difficulty</li></ul><h3 id="chapter-5-—-data-the-field-s-real-bottleneck" tabindex="-1">Chapter 5 — Data: the field&#39;s real bottleneck <a class="header-anchor" href="#chapter-5-—-data-the-field-s-real-bottleneck" aria-label="Permalink to &quot;Chapter 5 — Data: the field&#39;s real bottleneck&quot;">​</a></h3><ul><li>5.1 The data pyramid</li><li>5.2 Tier 1: real-robot teleoperation data</li><li>5.3 Tier 2: handheld collection devices — deleting the robot from the data</li><li>5.4 Tier 3: human video</li><li>5.5 Tier 4: simulation and synthesis</li><li>5.6 Tier 5: world models as data engines</li><li>5.7 Data mixing, cleaning and scaling laws</li><li>5.8 Five operational conclusions from this chapter</li></ul><h3 id="chapter-6-—-methods-pretraining-reinforcement-learning-test-time-scaling" tabindex="-1">Chapter 6 — Methods: pretraining, reinforcement learning, test-time scaling <a class="header-anchor" href="#chapter-6-—-methods-pretraining-reinforcement-learning-test-time-scaling" aria-label="Permalink to &quot;Chapter 6 — Methods: pretraining, reinforcement learning, test-time scaling&quot;">​</a></h3><ul><li>6.0 A panorama of training stages</li><li>6.1 The BC fine-tuning recipe: one controlled study everyone should read</li><li>6.2 Online RL: eliminating covariate shift directly</li><li>6.3 Offline and iterative RL: the realistic route on real hardware</li><li>6.4 RL inside a world model: driving rollout cost to zero</li><li>6.5 Preference optimisation: no reward, no critic</li><li>6.6 Reward models and verifiers: VLA&#39;s referee problem</li><li>6.7 Test-time scaling: without changing a single weight</li><li>6.8 Continual learning and skill accumulation</li></ul><h3 id="chapter-7-—-efficiency-and-deployment-three-billion-parameters-at-30-hz" tabindex="-1">Chapter 7 — Efficiency and deployment: three billion parameters at 30 Hz <a class="header-anchor" href="#chapter-7-—-efficiency-and-deployment-three-billion-parameters-at-30-hz" aria-label="Permalink to &quot;Chapter 7 — Efficiency and deployment: three billion parameters at 30 Hz&quot;">​</a></h3><ul><li>7.0 First work out where your bottleneck actually is</li><li>7.1 Training-free wins: caching and token reduction</li><li>7.2 Quantisation</li><li>7.3 Pruning and recovery</li><li>7.4 Parallelism and speculative decoding</li><li>7.5 Few-step action generation</li><li>7.6 Dropping whole branches at inference</li><li>7.7 System-level optimisation and asynchrony</li><li>7.8 A deployment selection guide</li></ul><h3 id="chapter-8-—-benchmarks-and-evaluation-the-dirtiest-part-of-the-field" tabindex="-1">Chapter 8 — Benchmarks and evaluation: the dirtiest part of the field <a class="header-anchor" href="#chapter-8-—-benchmarks-and-evaluation-the-dirtiest-part-of-the-field" aria-label="Permalink to &quot;Chapter 8 — Benchmarks and evaluation: the dirtiest part of the field&quot;">​</a></h3><ul><li>8.1 Why VLA evaluation is especially hard</li><li>8.2 Simulation benchmarks</li><li>8.3 Real-robot evaluation: the only thing that truly counts</li><li>8.4 World models as evaluators: ranking policies without hardware</li><li>8.5 Generalisation and robustness diagnostics: the most informative evaluations</li><li>8.6 Statistical methodology: what this field lacks most</li><li>8.7 Metrics: not only success rate</li><li>8.8 The order in which to read a VLA paper&#39;s tables</li></ul><h3 id="chapter-9-—-open-challenges-and-research-trends" tabindex="-1">Chapter 9 — Open challenges and research trends <a class="header-anchor" href="#chapter-9-—-open-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 9 — Open challenges and research trends&quot;">​</a></h3><ul><li>9.0 The shared methodological debt that emerged from reading every paper</li><li>9.1 Ten directions the community already agrees on</li><li>9.2 Five unsolved problems the author considers most important</li><li>9.3 Six observed trends as of mid-2026</li><li>9.4 Three high-return routes if you are choosing a topic</li></ul><h3 id="chapter-10-—-complete-paper-list-2025-06-–-2026-08" tabindex="-1">Chapter 10 — Complete paper list (2025.06 – 2026.08) <a class="header-anchor" href="#chapter-10-—-complete-paper-list-2025-06-–-2026-08" aria-label="Permalink to &quot;Chapter 10 — Complete paper list (2025.06 – 2026.08)&quot;">​</a></h3><p>Twenty-one groups: foundations; surveys and positions; VLA foundation models and generalist policies; action representation, action heads and generative paradigms; dual-system and hierarchical designs; 3D and spatial understanding; reasoning VLA; memory; tactile, force and multi-sensory; latent actions, human video and cross-embodiment; world-action models; RL and post-training; reward models, verifiers, failure detection and test-time scaling; efficiency, compression and deployment; datasets, data engines and generative augmentation; simulators, benchmarks and evaluation methodology; safety, robustness, attack and defence; navigation and mobility; dexterous hands, humanoids and whole-body control; autonomous-driving VLA; and newly released work not yet classified.</p><h3 id="chapter-11-—-paper-by-paper-walkthrough-ordered-by-arxiv-id" tabindex="-1">Chapter 11 — Paper-by-paper walkthrough, ordered by arXiv id <a class="header-anchor" href="#chapter-11-—-paper-by-paper-walkthrough-ordered-by-arxiv-id" aria-label="Permalink to &quot;Chapter 11 — Paper-by-paper walkthrough, ordered by arXiv id&quot;">​</a></h3><ul><li>11.0 How to use this chapter</li><li>11.1 The foundational period (2021.12 – 2025.03)</li><li>11.2 June – September 2025</li><li>11.3 November 2025 – March 2026</li><li>11.4 April – August 2026</li><li>11.5 August 2026, the most recent batch</li></ul><h3 id="appendices" tabindex="-1">Appendices <a class="header-anchor" href="#appendices" aria-label="Permalink to &quot;Appendices&quot;">​</a></h3><ul><li>Appendix A — Getting started: a four-week plan assuming one 24 GB GPU, common open-source resources, and what your first project should be</li><li>Appendix B — Ten things to check when reading a VLA paper</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/embodied-ai-general">General Embodied AI</a> — the wider stack VLA sits inside</li><li><a href="/notes/en/tutorials/world-action-models">World-Action Models</a> — family 3.6 developed at full length</li><li><a href="/notes/en/tutorials/video-for-embodied-ai">Video Generation for Embodied AI</a> — where the data engines in §5.6 come from</li></ul>',37)])])}const m=i(l,[["render",o]]);export{p as __pageData,m as default};
